// === Tab: mySketch.js ===
/*

	BG Music by Titanic: My Heart Will Go On – James Horner / Céline Dion [piano cover]:
												https://www.youtube.com/watch?v=HSgN5EWKi9Y
*/

let countdown=true
let counter=0
let cols, rows;
let scale = 20;
let flowFields = [];
let zoff = 0;
let a=0
let Speed=20
let RangeStart=0
let RangeStop=255
let strkWgt=13.5
let theY=0

function setup(){
  createCanvas(windowWidth, windowHeight);
  frameRate(10);
	cols = floor(width/scale);
	rows = floor(height/scale);
  for(let x = 0;x<cols*rows;x++)
	{
    flowFields[x] = createVector(0, 0);
   }
}

function draw()
{
	inc=a+random(-.004,.004)
	if(countdown==true)	counter=counter-Speed
	else counter=counter+Speed

	if(counter>=255) countdown=true
	else if(counter<=0) countdown=false

  background(counter); 
  let yoff = 0;
  for(let y = 0;y < rows;y++)
	{
    let xoff = 0;
    for(let x = 0; x<cols;x++)
		{
      let index = x+y*cols;
      let angle = noise(xoff, yoff, zoff) * TWO_PI* 8;
      let v = p5.Vector.fromAngle(angle);
      v.setMag(1);
      flowFields[index] = v;
			beginShape()	
				let hue = (map(v.heading(), -PI, PI, RangeStart, RangeStop)) % 360;
				let saturation = map(angle, 0, TWO_PI * 8, 0, 200);
				let lightness  = map(angle, 0, TWO_PI * 8, 200, 80);
				stroke(hue); 
				strokeWeight(strkWgt)
				push();
					translate(x*scale, y*scale);
					rotate(v.heading());
					vertex(x*scale-scale, y*scale)
					vertex(x*scale+scale, y*scale+scale)
					vertex(x*scale-random(-100,100), y*scale-scale)
				pop();
			endShape(CLOSE)
      xoff+=inc;
    }
    yoff+= inc;
	}
 	zoff += 0.002 + map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0.001, 0.01);
	theY+=.25
	push();
		translate(width/2, 20+theY)
		noFill()
		noStroke();
		size=5
		stroke(0)
		strokeWeight(4)
		circle(0,0,20)
		line(10,0,40,0)
		line(15,0,10,-10)
		line(15,0,15,-9)
		line(40,0,40,-5)
		line(37,0,37,-5)
  pop();
}

